def f(g):
    import numpy as np
    a=np.array(g); H,W=a.shape
    seen=np.zeros((H,W),bool); out=[[0]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if a[i][j]==0 or seen[i][j]: continue
            # BFS component
            comp=[(i,j)]; seen[i][j]=True; q=[(i,j)]
            while q:
                r,c=q.pop()
                for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<H and 0<=nc<W and a[nr][nc]!=0 and not seen[nr][nc]:
                        seen[nr][nc]=True; comp.append((nr,nc)); q.append((nr,nc))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            top,bot,left,right=min(rs),max(rs),min(cs),max(cs)
            layers={}
            for r,c in comp:
                d=min(r-top,bot-r,c-left,right-c)
                layers.setdefault(d,set()).add(a[r][c])
            cols=[next(iter(layers[d])) for d in sorted(layers)]
            rev={cols[k]:cols[len(cols)-1-k] for k in range(len(cols))}
            for r,c in comp:
                out[r][c]=rev[a[r][c]]
    return out
